// Guided tours: short trips that fly the map, switch layers or open a step of a Time travel story.
import type { ProjectionId } from '../engine/projections';
import type { StoryKind } from '../modes/stories';

export interface TourStep {
  title_en: string; title_es: string; en: string; es: string; icon?: string; fly?: [number, number, number]; projection?: ProjectionId; stack?: string[]; mode?: string;
  /** A story step to show: [collection, story id, step number (from 1)]. */
  story?: [StoryKind, string, number];
}
/** `group` places the tour in the list: our planet (none), cities through time, history and culture, or life through time. */
export interface Tour { icon: string; en: string; es: string; group?: 'cities' | 'history' | 'life'; steps: TourStep[] }

/** A stop that opens a story step and then flies to [lon, lat, zoom] (null keeps the step's own view). */
const at = (story: [StoryKind, string, number], fly: [number, number, number] | null, title_en: string, title_es: string, en: string, es: string): TourStep =>
  ({ story, ...(fly ? { fly } : {}), title_en, title_es, en, es });

